  "excludes.advisoryImmichDb": "Immich は写真ごとのアルバム、顔、日付を PostgreSQL のデータベースに保存しています。そのデータベースは、このコンテナとは別のコンテナで動いているため、このバックアップには含まれていません。ここから復元しても、写真は戻りますが、アルバムも顔も日付も戻りません。BombVault はそのデータベースコンテナをバックアップする際に自動でダンプを取るので、スケジュールに入っているか確かめてください。",
  "excludes.advisoryNextcloudDb": "Nextcloud はアカウント、共有、タグをデータベースに保存しています。そのデータベースは通常、別のコンテナで動いているため、このバックアップには含まれていません。ファイルは戻りますが、共有は戻りません。BombVault はそのデータベースコンテナをバックアップする際に自動でダンプを取るので、スケジュールに入っているか確かめてください。",
