  "rcloneRemote.hint": "Windows や Samba の共有、または Nextcloud などの WebDAV サーバーに、ホストへマウントせずに接続します。restic はマウントした CIFS 共有にリポジトリを置くことを推奨しておらず、この方法ならマウントそのものが不要になります。パスワードは rclone に渡され、rclone 独自の形式で保存されるため、平文のまま保持されることはありません。restic も rclone も NFS を扱えないため、ここでは NFS を選べません。NFS を使う場合は、エクスポートを Unraid にマウントし、バックアップパスをそこに設定してください。",
