  "mcp.setupForm": "{app} の {ui} に次の値を入力してください。",
  "mcp.setupOther": "Streamable HTTP を話すクライアントならどれでも使えます。リモート MCP サーバーを求められる場所に入力し、キーは 2 つのヘッダーのどちらかに入れてください。",
  "mcp.setupWhere": "ファイルの場所",
