  "mcp.keyFileLine": "キーをテキストファイルに X-API-Key: <key> という行で保存し、そのファイルのパスを設定に入れてください。{app} はパスだけを保持するので、キーは設定にもプロセス一覧にも現れません。",
  "mcp.keyFileJsonTip": "この JSON ファイルでは、パスを C:/Users/sam/bombvault-key.txt のようにスラッシュで書いてください。バックスラッシュ 1 つは JSON として無効です。キーファイルのパスには空白を入れないでください。Windows の {app} は、空白を含むパスを 2 つに分けて npx に渡します。",
  "mcp.keyEnv": "{app} は環境変数 {var} からキーを読み取ります。",
  "mcp.keyEnvTip": "ユーザー環境変数として一度設定してください。Windows では 設定、システム、バージョン情報、システムの詳細設定、環境変数 で、macOS と Linux ではシェルのプロファイルで設定します。その後 {app} を再起動してください。プロンプトで setx や export を使って入力すると、キーがシェルの履歴に残ります。macOS で Dock や Finder から起動したアプリはシェルのプロファイルを読みません。キーだけを ~/.bombvault-key のようなファイルに入れ、ターミナルで launchctl setenv {var} \"$(cat ~/.bombvault-key)\" を実行してから {app} を開き直してください。Mac を再起動するたびに繰り返します。",
  "mcp.keyEnvUnsure": "{app} がキーの代わりに変数名を送る場合は、その位置にキーを直接書き込み、そのファイルは自分だけで管理してください。",
  "mcp.keyPrompt": "{app} はサーバーを初めて起動するときにキーを尋ね、独自のシークレットストレージに保存します。そのためファイルにキーは含まれません。",
  "mcp.keyDotenv": "{app} は {file} の {var}=<key> という行からキーを読み取ります。このファイルは自分だけで管理してください。",
  "mcp.keyInFile": "{app} はほかの場所からキーを読み取れないため、キーはこのファイルに平文で置かれます。ファイルは自分だけで管理し、共有フォルダーやバージョン管理に入れないでください。",
  "mcp.keyInApp": "{app} はキーを独自の設定に保存します。ドキュメントを見る限り、暗号化はされません。その設定を開ける人なら誰でもキーを読めます。",
  "mcp.keyCredential": "{app} はキーを認証情報として暗号化して保存します。このキーで Bearer Auth 型の認証情報を作成し、ノードで選択してください。ワークフローには認証情報の名前しか残りません。",
  "mcp.keyVendor": "{app} はキーを提供元のサーバーに保存し、呼び出しのたびに送信します。",
  "mcp.keyOther": "クライアントが環境変数、シークレットの入力、システムのキーチェーンからキーを読み取れるなら、キーを設定に書き込む代わりにそれを使ってください。",
  "mcp.certPlaceholder": "BombVault は独自の証明書を使います。設定は Node.js をその証明書に向けているので、ファイルをダウンロードし、証明書のプレースホルダーをそのパスに置き換えてください。",
  "mcp.certEnv": "BombVault は独自の証明書を使います。{app} が拒否する場合は、環境変数 {var} にダウンロードしたファイルのパスを設定し、{app} を再起動してください。",
  "mcp.certEnvTip": "ユーザー環境変数を設定する場所で設定してください。Windows では 設定、システム、バージョン情報、システムの詳細設定、環境変数 で、macOS と Linux ではシェルのプロファイルで、コンテナーではその設定で、ファイルをマウントしたうえで設定します。BombVault が新しい証明書を発行したら、そのたびにダウンロードし直してください。macOS で Dock や Finder から起動したアプリはシェルのプロファイルを読みません。その場合はターミナルでファイルのパスを付けて launchctl setenv {var} を実行し、アプリを開き直してください。Mac を再起動するたびに繰り返します。",
  "mcp.certSystem": "BombVault は独自の証明書を使います。{app} が拒否する場合は、ダウンロードしたファイルをシステムの信頼された証明書に追加し、{app} を再起動してください。",
  "mcp.certSystemTip": "Windows ではファイル名を bombvault-cert.crt に変えてから開き、証明書のインストール、現在のユーザー、証明書をすべて次のストアに配置する、信頼されたルート証明機関 を選びます。または、ファイルのパスを付けて certutil -user -addstore Root を実行します。macOS ではキーチェーンアクセスでログインキーチェーンに追加し、常に信頼 に設定します。Linux では拡張子 .crt を付けて /usr/local/share/ca-certificates にコピーし、update-ca-certificates を実行します。",
  "mcp.certOwnList": "BombVault は独自の証明書を使いますが、{app} は追加できない独自のリストで証明書を確認します。BombVault の証明書が拒否される場合は、公的に信頼された証明書を持つリバースプロキシ経由で BombVault に接続してください。",
  "mcp.certOther": "BombVault は独自の証明書を使います。クライアントにダウンロードしたファイルを指定するか、システムの信頼された証明書に追加してください。",
  "mcp.certOtherTip": "Node.js 上のクライアントは NODE_EXTRA_CA_CERTS からファイルを読み込みます。ほとんどのほかのクライアントはシステムが信頼する証明書を使います。証明書の確認は決して無効にしないでください。",
  "mcp.waitTitle": "最初の呼び出しを待っています",
