  "mcp.waitLine": "{app} が BombVault を呼び出すのを待っています",
  "mcp.waitLineOther": "クライアントが BombVault を呼び出すのを待っています",
  "mcp.waitHint": "{app} を再起動して新しいサーバーを読み込ませ、一度 BombVault を使わせてください。最初の呼び出しでここが緑になります。",
  "mcp.waitHintOther": "クライアントを接続してください。最初の呼び出しでここが緑になります。",
