  "oauth.heading": "BombVault へのアクセスを許可しますか?",
  "oauth.asks": "{name} がこの BombVault の MCP サーバーへのアクセスを求めています。",
  "oauth.reads": "バックアップの状態を読めるようになります。何が保護されているか、各項目が最後にいつバックアップされたか、各実行の結果、そのログの内容です。復元、削除、設定はこの Web インターフェースに残ります。",
  "oauth.unverified": "BombVault はこのクライアントを知らず、上の名前はクライアント自身が付けたものです。このサインインを今しがた自分で始めた場合だけ許可してください。",
  "oauth.startedHere": "このサインインを今しがた自分で始めた場合だけ許可してください。他の人から送られたリンクだと、その人の {name} アカウントがあなたの BombVault につながるおそれがあります。",
  "oauth.loopback": "このクライアントはあなたのコンピューター上のプログラムに戻ります。そこにあるどのプログラムでもこのクライアントになりすませます。このサインインを今しがた自分で始めた場合だけ許可してください。",
  "oauth.allowStartHint": "オンにすると、クライアントはバックアップを開始し、自分が開始したものを取り消すこともできます。制限はキーと同じです。バックアップ中は、終わるまで実行中のコンテナーが停止します。あとで設定、連携、MCP サーバーのタイルで変更できます。",
