  "oauth.errorUnknownClient": "このクライアントはここに登録されていないか、登録の期限が切れています。クライアントから BombVault を削除して、もう一度追加してください。",
  "oauth.errorBadRedirect": "このリクエストは、クライアントが登録したことのない戻り先アドレスを指定しているため、BombVault はそこへ送りません。",
