  "mcp.oauthHint": "ChatGPT、claude.ai の Claude など、キーを受け取れないサービス向けです。これらは BombVault のページへあなたを送り、そこでログインパスワードでサインインして許可します。サービスは自社のサーバーから BombVault を呼び出すため、BombVault は下の公開アドレスでインターネットから到達でき、ブラウザーが信頼する証明書を持っている必要があります。オフにすると、すべてのクライアントがサインアウトされます。",
