  "mcp.setupClaudeAi": "claude.ai で設定、コネクターを開き、カスタムコネクターを追加を選びます。名前を付けてコネクター URL を貼り付け、OAuth のクライアント ID とシークレットは空のままにして追加します。続けて接続を選びます。",
  "mcp.copyConnector": "コネクター URL をコピー",
